#!/usr/bin/env python3
"""Token Alert Terminal Checker - Reads session data and displays usage status."""

import json
from pathlib import Path

# Read deterministic sample data
DATA_FILE = Path('input/session_data.json')

def load_session_data():
    """Load session data from JSON file."""
    with open(DATA_FILE, 'r', encoding='utf-8') as f:
        return json.load(f)

def get_warning_level(percentage, thresholds):
    """Determine warning level based on percentage and thresholds."""
    levels = [
        (100, "🔴 CRITICAL", "Token limit reached!"),
        (95, "🚨 EMERGENCY", "Almost out of tokens!"),
        (90, "🔴 Critical Warning", "Very low tokens remaining"),
        (75, "🔶 High Warning", "Low tokens remaining"),
        (50, "🟠 Medium Warning", "Moderate token usage"),
        (25, "🟡 Low Warning", "Token usage increasing"),
        (0, "✅ OK", "Token usage is healthy")
    ]

    for threshold, icon, status in levels:
        if percentage >= threshold:
            return icon, status, threshold

    return "✅ OK", "Token usage is healthy", 0

def create_progress_bar(percentage, total_bars=25):
    """Create a box-style progress bar with ▰/▱ characters."""
    filled = int(percentage / 100 * total_bars)
    empty = total_bars - filled
    bar = "▰" * filled + "▱" * empty
    return bar

def estimate_remaining_sessions(remaining_tokens, avg_session=50000):
    """Estimate remaining sessions based on average token usage."""
    sessions = remaining_tokens // avg_session
    if sessions == 0:
        return "<1 Session"
    elif sessions == 1:
        return "~1 Session"
    else:
        return f"~{sessions} Sessions"

def main():
    # Load data
    data = load_session_data()

    limit = data['limit']
    used = data['used']
    thresholds = data['thresholds']

    # Calculate percentage
    percentage = (used / limit) * 100
    remaining = limit - used

    # Get warning level
    icon, status, threshold = get_warning_level(percentage, thresholds)

    # Create progress bar
    progress_bar = create_progress_bar(percentage)

    # Estimate sessions
    sessions = estimate_remaining_sessions(remaining)

    # Display output
    print(f"{icon} Token Alert: {status}")
    print()
    print(f"{icon} {progress_bar} {percentage:.1f}%")
    print(f"{used:,} / {limit:,} Tokens verwendet")
    print()
    print(f"⚠️ Status: {status} (Zone: {threshold}%+)")
    print(f"💡 Verbleibend: ~{remaining:,} Tokens")
    print(f"⏰ Geschätzte Sessions: {sessions}")
    print()

    # Recommendations based on level
    if percentage >= 90:
